select.if:
select pid,shareholders_code as shareholdersCode,name_,'PSN' type,domestic_or_foreign as domesticOrForeign,
identify_type as identifyType,identify_number as identifyNumber,hole_share_amount as holeShareAmount,
shareholding_proportion as shareholdingProportion,case when dj_status is null then to_nchar('0') else
dj_status end as isDj,null stateOwned ,status ,status_comment as
statusComment,is_black as isBlack from bus_rel_psn
where is_shareholder = '1'

    and shareholders_code = #{shareholdersCode}


    and domestic_or_foreign like #{domesticOrForeign}


    and name_ = #{name_}


    and shareholding_proportion = #{shareholdingProportion}


    and 1 != 1

select pid,shareholders_code as shareholdersCode,org_name as name_,'ORG' as type,domestic_or_foreign as
domesticOrForeign,
identify_type as identifyType,unisc_code as identifyNumber ,hole_share_amount as holeShareAmount,
shareholding_proportion as shareholdingProportion,case when dj_status is null then to_nchar('0') else
dj_status end as isDj,state_owned as stateOwned ,status
,status_comment as statusComment,is_black as isBlack from bus_rel_org
where is_shareholder = '1'

    and shareholders_code = #{shareholdersCode}


    and domestic_or_foreign like #{domesticOrForeign}


    and org_name = #{name_}


    and shareholding_proportion = #{shareholdingProportion}


    and state_owned = #{stateOwned}
